package lombok.javac.handlers;

import static lombok.javac.handlers.JavacHandlerUtil.*;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Iterator;

import com.sun.source.tree.MethodInvocationTree;
import com.sun.source.tree.TreeVisitor;
import com.sun.source.util.TreeScanner;
import com.sun.tools.javac.code.Flags;
import com.sun.tools.javac.tree.JCTree;
import com.sun.tools.javac.tree.JCTree.JCAnnotation;
import com.sun.tools.javac.tree.JCTree.JCBlock;
import com.sun.tools.javac.tree.JCTree.JCCase;
import com.sun.tools.javac.tree.JCTree.JCClassDecl;
import com.sun.tools.javac.tree.JCTree.JCCompilationUnit;
import com.sun.tools.javac.tree.JCTree.JCExpression;
import com.sun.tools.javac.tree.JCTree.JCIdent;
import com.sun.tools.javac.tree.JCTree.JCImport;
import com.sun.tools.javac.tree.JCTree.JCMethodDecl;
import com.sun.tools.javac.tree.JCTree.JCMethodInvocation;
import com.sun.tools.javac.tree.JCTree.JCStatement;
import com.sun.tools.javac.tree.JCTree.JCVariableDecl;
import com.sun.tools.javac.util.Context;
import com.sun.tools.javac.util.List;
import com.sun.tools.javac.util.ListBuffer;
import com.sun.tools.javac.util.Name;
import com.sun.tools.javac.util.Options;

import lombok.ConfigurationKeys;
import lombok.core.AST.Kind;
import lombok.core.AnnotationValues;
import lombok.core.configuration.FlagUsageType;
import lombok.experimental.Helper;
import lombok.javac.Javac;
import lombok.javac.JavacAnnotationHandler;
import lombok.javac.JavacAugments;
import lombok.javac.JavacNode;
import lombok.javac.JavacTreeMaker;
import lombok.javac.LombokOptions;
import lombok.spi.Provides;

@Provides
public class HandleHelper extends JavacAnnotationHandler<Helper> {
	private List<JCStatement> getStatementsFromJcNode(JCTree tree) {
		if (tree instanceof JCBlock) return ((JCBlock) tree).stats;
		if (tree instanceof JCCase) return ((JCCase) tree).stats;
		return null;
	}

	private void setStatementsOfJcNode(JCTree tree, List<JCStatement> statements) {
		if (tree instanceof JCBlock) ((JCBlock) tree).stats = statements;
		else if (tree instanceof JCCase) ((JCCase) tree).stats = statements;
		else throw new IllegalArgumentException("Can't set statements on node type: " + tree.getClass());
	}

	@Override public void handle(AnnotationValues<Helper> annotation, JCAnnotation ast, final JavacNode annotationNode) {
		FlagUsageType helperFlagUsage = annotationNode.getAst().readConfiguration(ConfigurationKeys.HELPER_FLAG_USAGE);
		FlagUsageType experimentalFlagUsage = annotationNode.getAst().readConfiguration(ConfigurationKeys.EXPERIMENTAL_FLAG_USAGE);
		FlagUsageType selectedFlagUsage = null;
		String selectedFeatureName = null;
		if (helperFlagUsage == FlagUsageType.ERROR) {
			selectedFlagUsage = helperFlagUsage;
			selectedFeatureName = "@Helper";
		} else if (experimentalFlagUsage == FlagUsageType.ERROR) {
			selectedFlagUsage = experimentalFlagUsage;
			selectedFeatureName = "any lombok.experimental feature";
		} else if (helperFlagUsage == FlagUsageType.WARNING) {
			selectedFlagUsage = helperFlagUsage;
			selectedFeatureName = "@Helper";
		} else {
			selectedFlagUsage = experimentalFlagUsage;
			selectedFeatureName = "any lombok.experimental feature";
		}
		if (selectedFlagUsage != null) {
			String flaggedMessage = "Use of " + selectedFeatureName + " is flagged according to lombok configuration.";
			if (selectedFlagUsage == FlagUsageType.WARNING) {
				annotationNode.addWarning(flaggedMessage);
			} else if (selectedFlagUsage == FlagUsageType.ERROR) {
				annotationNode.addError(flaggedMessage);
			}
		}

		Context javacContext = annotationNode.getContext();
		Options javacOptions = Options.instance(javacContext);
		boolean hasIdeOption = false;
		boolean hasBackgroundCompilationOption = false;
		for (String optionName : javacOptions.keySet()) {
			if ("ide".equals(optionName)) {
				hasIdeOption = true;
			} else if ("backgroundCompilation".equals(optionName)) {
				hasBackgroundCompilationOption = true;
			}
		}
		boolean netbeansEditor = false;
		if (hasIdeOption) {
			if (!hasBackgroundCompilationOption) {
				netbeansEditor = true;
			}
		}
		boolean deleteLombokAnnotations = LombokOptions.shouldDeleteLombokAnnotations(javacContext);
		String helperAnnotationName = Helper.class.getName();
		if (!netbeansEditor) {
			if (deleteLombokAnnotations) {
				JavacNode annotationParent = annotationNode.directUp();
				Kind annotationParentKind = annotationParent.getKind();
				JCTree annotationTree = annotationNode.get();
				if (annotationParentKind == Kind.FIELD || annotationParentKind == Kind.ARGUMENT || annotationParentKind == Kind.LOCAL) {
					JCVariableDecl annotatedVariable = (JCVariableDecl) annotationParent.get();
					ListBuffer<JCAnnotation> retainedVariableAnnotations = new ListBuffer<JCAnnotation>();
					for (JCAnnotation existingAnnotation : annotatedVariable.mods.annotations) {
						if (existingAnnotation != annotationTree) {
							retainedVariableAnnotations.append(existingAnnotation);
						}
					}
					annotatedVariable.mods.annotations = retainedVariableAnnotations.toList();
					if ((annotatedVariable.mods.flags & Javac.GENERATED_MEMBER) != 0) {
						JavacNode enclosingTypeNode = upToTypeNode(annotationNode);
						if (enclosingTypeNode != null) {
							if (isRecord(enclosingTypeNode)) {
								JavacHandlerUtil.RecordComponentReflect.deleteAnnotation((JCClassDecl) enclosingTypeNode.get(), annotatedVariable, annotationTree);
							}
						}
					}
					annotationParent.getAst().setChanged();
					JCCompilationUnit compilationUnit = (JCCompilationUnit) annotationNode.top().get();
					for (JCTree unitDefinition : compilationUnit.defs) {
						if (unitDefinition instanceof JCImport) {
							JCImport importDecl = (JCImport) unitDefinition;
							if (!importDecl.staticImport) {
								String importedType = Javac.getQualid(importDecl).toString();
								if (!importedType.isEmpty()) {
									if (importedType.equals(helperAnnotationName)) {
										JavacAugments.JCImport_deletable.set(importDecl, true);
									}
								}
							}
						}
					}
				} else if (annotationParentKind == Kind.METHOD) {
					JCMethodDecl annotatedMethod = (JCMethodDecl) annotationParent.get();
					ListBuffer<JCAnnotation> retainedMethodAnnotations = new ListBuffer<JCAnnotation>();
					for (JCAnnotation existingAnnotation : annotatedMethod.mods.annotations) {
						if (existingAnnotation != annotationTree) {
							retainedMethodAnnotations.append(existingAnnotation);
						}
					}
					annotatedMethod.mods.annotations = retainedMethodAnnotations.toList();
					annotationParent.getAst().setChanged();
					JCCompilationUnit compilationUnit = (JCCompilationUnit) annotationNode.top().get();
					for (JCTree unitDefinition : compilationUnit.defs) {
						if (unitDefinition instanceof JCImport) {
							JCImport importDecl = (JCImport) unitDefinition;
							if (!importDecl.staticImport) {
								String importedType = Javac.getQualid(importDecl).toString();
								if (!importedType.isEmpty()) {
									if (importedType.equals(helperAnnotationName)) {
										JavacAugments.JCImport_deletable.set(importDecl, true);
									}
								}
							}
						}
					}
				} else if (annotationParentKind == Kind.TYPE) {
					try {
						JCClassDecl annotatedClass = (JCClassDecl) annotationParent.get();
						ListBuffer<JCAnnotation> retainedTypeAnnotations = new ListBuffer<JCAnnotation>();
						for (JCAnnotation existingAnnotation : annotatedClass.mods.annotations) {
							if (existingAnnotation != annotationTree) {
								retainedTypeAnnotations.append(existingAnnotation);
							}
						}
						annotatedClass.mods.annotations = retainedTypeAnnotations.toList();
					} catch (ClassCastException unusualAnnotationParent) {
						// Keep helper processing going if this parent is an unusual type-like node.
					}
					annotationParent.getAst().setChanged();
					JCCompilationUnit compilationUnit = (JCCompilationUnit) annotationNode.top().get();
					for (JCTree unitDefinition : compilationUnit.defs) {
						if (unitDefinition instanceof JCImport) {
							JCImport importDecl = (JCImport) unitDefinition;
							if (!importDecl.staticImport) {
								String importedType = Javac.getQualid(importDecl).toString();
								if (!importedType.isEmpty()) {
									if (importedType.equals(helperAnnotationName)) {
										JavacAugments.JCImport_deletable.set(importDecl, true);
									}
								}
							}
						}
					}
				}
			}
		}

		JavacNode annotatedType = annotationNode.up();
		JavacNode containingBlock = annotatedType == null ? null : annotatedType.directUp();
		List<JCStatement> origStatements = getStatementsFromJcNode(containingBlock == null ? null : containingBlock.get());
		if (annotatedType == null || annotatedType.getKind() != Kind.TYPE || origStatements == null) {
			annotationNode.addError("@Helper is legal only on method-local classes.");
			return;
		}

		JCClassDecl annotatedType_ = (JCClassDecl) annotatedType.get();
		Iterator<JCStatement> statementIterator = origStatements.iterator();
		while (statementIterator.hasNext()) {
			JCStatement candidateStatement = statementIterator.next();
			if (candidateStatement == annotatedType_) {
				break;
			}
		}

		java.util.List<String> knownMethodNames = new ArrayList<String>();
		for (JavacNode child : annotatedType.down()) {
			if (child.getKind() != Kind.METHOD) {
				continue;
			}
			JCTree childTree = child.get();
			String methodName = child.getName();
			if (childTree instanceof JCMethodDecl) {
				JCMethodDecl methodDecl = (JCMethodDecl) childTree;
				if (methodDecl.name != null) {
					methodName = methodDecl.name.toString();
				}
				if (methodDecl.mods != null && (methodDecl.mods.flags & Flags.GENERATEDCONSTR) != 0) {
					continue;
				}
			}
			if (methodName != null && !methodName.isEmpty() && methodName.charAt(0) != '<') {
				knownMethodNames.add(methodName);
			}
		}

		Collections.sort(knownMethodNames);
		final String[] knownMethodNames_ = knownMethodNames.toArray(new String[0]);
		final Name helperName = annotationNode.toName("$" + annotatedType_.name);
		final boolean[] helperUsed = new boolean[1];
		final JavacTreeMaker maker = annotationNode.getTreeMaker();
		final java.util.List<JCMethodInvocation> invocations = new ArrayList<JCMethodInvocation>();
		TreeVisitor<Void, Void> invocationCollector = new TreeScanner<Void, Void>() {
			@Override public Void visitMethodInvocation(MethodInvocationTree node, Void p) {
				invocations.add((JCMethodInvocation) node);
				return super.visitMethodInvocation(node, p);
			}
		};
		while (statementIterator.hasNext()) {
			JCStatement remainingStatement = statementIterator.next();
			remainingStatement.accept(invocationCollector, null);
		}

		final java.util.List<JCTree> generatedPieces = new ArrayList<JCTree>();
		com.sun.tools.javac.tree.TreeScanner generatedPieceCollector = new com.sun.tools.javac.tree.TreeScanner() {
			@Override public void scan(JCTree tree) {
				if (tree == null) return;
				generatedPieces.add(tree);
				super.scan(tree);
			}
		};

		for (JCMethodInvocation invocation : invocations) {
			if (invocation.meth instanceof JCIdent) {
				JCIdent invokedIdent = (JCIdent) invocation.meth;
				if (invokedIdent.name != null && Arrays.binarySearch(knownMethodNames_, invokedIdent.name.toString()) >= 0) {
					JCExpression helperReceiver = maker.Ident(helperName);
					JCExpression rewrittenInvocation = maker.Select(helperReceiver, invokedIdent.name);
					invocation.meth = rewrittenInvocation;
					generatedPieces.clear();
					generatedPieceCollector.scan(rewrittenInvocation);
					for (JCTree generatedPiece : generatedPieces) {
						JavacAugments.JCTree_generatedNode.set(generatedPiece, annotationNode.get());
						boolean parameterNode = generatedPiece instanceof JCVariableDecl && ((((JCVariableDecl) generatedPiece).mods.flags & Flags.PARAMETER) != 0);
						if (!netbeansEditor || parameterNode) {
							generatedPiece.pos = annotationNode.getStartPos();
							Javac.storeEnd(generatedPiece, annotationNode.getEndPosition(), (JCCompilationUnit) annotationNode.top().get());
						}
					}
					helperUsed[0] = true;
				}
			}
		}

		if (!helperUsed[0]) {
			annotationNode.addWarning("No methods of this helper class are ever used.");
			return;
		}

		ListBuffer<JCStatement> newStatements = new ListBuffer<JCStatement>();
		boolean helperInstanceInserted = false;
		for (JCStatement originalStatement : origStatements) {
			newStatements.append(originalStatement);
			if (helperInstanceInserted || originalStatement != annotatedType_) {
				continue;
			}
			helperInstanceInserted = true;
			Name helperTypeName = annotatedType_.name;
			JCExpression helperInit = maker.NewClass(null, List.<JCExpression>nil(), maker.Ident(helperTypeName), List.<JCExpression>nil(), null);
			JCExpression helperType = maker.Ident(helperTypeName);
			JCVariableDecl helperDeclaration = maker.VarDef(maker.Modifiers(Flags.FINAL), helperName, helperType, helperInit);
			generatedPieces.clear();
			generatedPieceCollector.scan(helperDeclaration);
			for (JCTree generatedPiece : generatedPieces) {
				JavacAugments.JCTree_generatedNode.set(generatedPiece, annotationNode.get());
				boolean parameterNode = generatedPiece instanceof JCVariableDecl && ((((JCVariableDecl) generatedPiece).mods.flags & Flags.PARAMETER) != 0);
				if (!netbeansEditor || parameterNode) {
					generatedPiece.pos = annotationNode.getStartPos();
					Javac.storeEnd(generatedPiece, annotationNode.getEndPosition(), (JCCompilationUnit) annotationNode.top().get());
				}
			}
			newStatements.append(helperDeclaration);
		}
		setStatementsOfJcNode(containingBlock.get(), newStatements.toList());
	}
}

